namespace Jira.Domain.Entities;
public sealed class IssueAssignee { public long TenantId { get; set; } public long ProjectId { get; set; } public long IssueId { get; set; } public long UserId { get; set; } public DateTimeOffset AssignedAt { get; set; } = DateTimeOffset.UtcNow; }
public sealed class IssueLabel { public long Id { get; set; } public long TenantId { get; set; } public long IssueId { get; set; } public string Label { get; set; } = ""; public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; }
public sealed class IssueRelease { public long TenantId { get; set; } public long ProjectId { get; set; } public long IssueId { get; set; } public long ReleaseId { get; set; } public string Kind { get; set; } = "FIX"; }
public sealed class ProjectComponent { public long Id { get; set; } public long TenantId { get; set; } public long ProjectId { get; set; } public string Name { get; set; } = ""; public string? Description { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow; public uint Version { get; set; } }
public sealed class ProjectRelease { public long Id { get; set; } public long TenantId { get; set; } public long ProjectId { get; set; } public string Name { get; set; } = ""; public string ReleaseVersion { get; set; } = ""; public string? Description { get; set; } public string Status { get; set; } = "UNRELEASED"; public DateOnly? ReleaseDate { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow; public uint Version { get; set; } }
public sealed class Sprint { public long Id { get; set; } public long TenantId { get; set; } public long ProjectId { get; set; } public long? BoardId { get; set; } public string Name { get; set; } = ""; public string? Goal { get; set; } public string Status { get; set; } = "PLANNED"; public DateOnly? StartDate { get; set; } public DateOnly? EndDate { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow; public uint Version { get; set; } }
public sealed class SprintIssue { public long SprintId { get; set; } public long IssueId { get; set; } public DateTimeOffset AddedAt { get; set; } = DateTimeOffset.UtcNow; }
